import{visible,answered,validate,payload}from'/core.mjs';
const schema=await(await fetch('/schema.json')).json(),key='alopex-hearing-v1', $=id=>document.getElementById(id);let state={a:{},notes:{},step:0,id:crypto.randomUUID(),project:'WEB-'+crypto.randomUUID().slice(0,8),updated:Date.now()};try{let old=JSON.parse(localStorage.getItem(key));if(old&&old.updated>Date.now()-30*86400000&&old.a&&old.notes)state=old;else localStorage.removeItem(key)}catch{}let sending=false,confirmed=null;const current=()=>schema.questions.filter(q=>visible(q,state.a));function save(){state.updated=Date.now();try{localStorage.setItem(key,JSON.stringify(state));$('saved').textContent='この端末に保存済み・'+new Date().toLocaleTimeString('ja-JP')}catch{$('saved').textContent='端末への保存ができません。画面を閉じると回答が失われます。'}updateProgress()}
function updateProgress(){let all=current(),n=all.filter(q=>answered(state.a[q.id])).length;$('count').textContent=`${n} / ${all.length}問回答 ・ ${Math.round(n/all.length*100)}%`;$('progress').value=n/all.length*100}
function el(tag,text,attrs={}){let x=document.createElement(tag);if(text)x.textContent=text;Object.entries(attrs).forEach(([k,v])=>x.setAttribute(k,v));return x}
function render(){confirmed=null;$('review').hidden=true;$('form').hidden=false;$('errors').textContent='';$('nav').replaceChildren();schema.sections.forEach((s,i)=>{let b=el('button',`${String(i+1).padStart(2,'0')} ${s}`,{type:'button'});if(i===state.step)b.setAttribute('aria-current','step');b.onclick=()=>{state.step=i;render();save()};$('nav').append(b)});$('content').replaceChildren(el('p',`SECTION ${state.step+1} / 16`,{class:'eyebrow'}),el('h2',schema.sections[state.step]));if(state.step===8)$('content').append(el('p','撮影：東基済／2時間5,000円・交通費別途（税の扱いは確認中）。AI画像：追加料金なし。実在の店舗・人物・商品を誤認させる用途は個別確認します。'));if(state.step===9)$('content').append(el('p','映像制作は別途見積もりです。'));
current().filter(q=>q.section===state.step).forEach(q=>{let f=el('fieldset',null,{id:q.id}),legend=el('legend',q.label);if(q.required)legend.append(el('span','必須',{class:'required'}));f.append(legend);if(['single','multi','design'].includes(q.type)){let wrap=el('div',null,{class:q.type==='design'?'choices designs':'choices'}),opts=q.type==='design'?['白基調','ダーク','ナチュラル','高級感','シンプル','ポップ']:q.options;opts.forEach((v,i)=>{let l=el('label',null,{class:'choice'}),input=el('input',null,{type:q.type==='multi'?'checkbox':'radio',name:q.id,value:v});input.checked=[state.a[q.id]].flat().includes(v);input.onchange=()=>{state.a[q.id]=q.type==='multi'?[...f.querySelectorAll('input:checked')].map(x=>x.value):v;save();if(schema.questions.some(z=>(z.when||z.unless)?.[0]===q.id))render()};if(q.type==='design'){let colors=[['#fff','#263a73'],['#18212c','#fff'],['#ece8da','#4c614a'],['#24211f','#d4b989'],['#f5f5f5','#222'],['#fff0e7','#cf4e69']][i];let sample=el('div',null,{class:'sample',style:`--bg:${colors[0]};--fg:${colors[1]};--font:${i===3?'serif':'sans-serif'}`});sample.append(el('small','YOUR BRAND'),el('strong','日々に、新しい価値を。'),el('i'));l.append(sample)}l.append(input,document.createTextNode(v));wrap.append(l)});f.append(wrap)}else{let input=el('input',null,{class:'field',type:q.type,id:q.id+'-input','aria-label':q.label,maxlength:'2000'});input.value=state.a[q.id]||'';input.oninput=()=>{state.a[q.id]=input.value;save()};f.append(input)}let d=el('details'),n=el('textarea',null,{'aria-label':q.label+' の備考',maxlength:'2000',placeholder:'補足・未確定のことなど（任意）'});n.value=state.notes[q.id]||'';n.oninput=()=>{state.notes[q.id]=n.value;save()};d.append(el('summary','備考を追加する（任意）'),n);f.append(d);$('content').append(f)});$('back').disabled=state.step===0;$('next').textContent=state.step===15?'回答を確認する →':'次の分野へ →';updateProgress()}
function errors(all){let invalid=all.map(q=>[q,validate(q,state.a[q.id])]).filter(x=>x[1]);if(!invalid.length)return false;state.step=invalid[0][0].section;render();$('errors').textContent=invalid.map(([q,e])=>`${q.label}：${e}`).join(' ／ ');$('errors').focus();return true}
$('form').onsubmit=e=>{e.preventDefault();if(errors(current().filter(q=>q.section===state.step)))return;if(state.step<15){state.step++;render();save();$('content').scrollIntoView({behavior:'smooth'})}else{if(errors(current()))return;confirmed=payload(schema,state.a,state.notes,state.id,state.project);$('form').hidden=true;$('review').hidden=false;$('summary').replaceChildren();schema.sections.forEach((name,i)=>{let h=el('h3',name),b=el('button','編集',{type:'button',class:'quiet'});b.onclick=()=>{state.step=i;render()};$('summary').append(h,b);current().filter(q=>q.section===i).forEach(q=>{let x=el('div',null,{class:'review-item'});x.append(el('strong',q.label),el('p',answered(state.a[q.id])?[state.a[q.id]].flat().join('、'):'未回答（任意）'));if(state.notes[q.id])x.append(el('p','備考：'+state.notes[q.id]));$('summary').append(x)})});$('review').querySelector('h2').focus()}};
$('back').onclick=()=>{state.step--;render();save()};$('erase').onclick=()=>{if(confirm('この端末に保存した回答を削除しますか？')){localStorage.removeItem(key);location.reload()}};
$('send').onclick=async()=>{if(sending||!confirmed)return;sending=true;$('send').disabled=true;$('sendstate').textContent='送信中…';try{let response=await fetch('/api/submit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(confirmed),signal:AbortSignal.timeout(30000)});let r=await response.json();if(!response.ok||!r.ok||r.submissionId!==state.id)throw Error(r.error||'保存確認ができませんでした');localStorage.removeItem(key);$('review').hidden=true;$('done').hidden=false;$('receipt').textContent='受付ID：'+r.submissionId;$('erase').hidden=true}catch(e){$('sendstate').textContent='送信できませんでした。回答は端末に保持しています。同じ受付IDで再試行してください。 '+e.message}finally{sending=false;$('send').disabled=false}};render();
